/* ST-LINK/V2 application firmware (rebuilds the image bit-for-bit).
   Range 0x08004000-0x0800E6DF.
   A few instructions use .inst.n/.inst.w raw encodings where the assembler would
   otherwise choose a different but equivalent encoding; the mnemonic is in the comment. */

    .syntax unified
    .cpu cortex-m3
    .thumb
    .section .app_image,"ax",%progbits
    .p2align 2

    .global  APP_Reset_Handler

g_pfnVectors_stlink_app:
    .word    0x20003910                               @ #0  _estack
    .word    APP_Reset_Handler + 1                    @ #1  Reset_Handler
    .word    APP_NMI_Handler + 1                      @ #2  NMI_Handler
    .word    APP_HardFault_Handler + 1                @ #3  HardFault_Handler
    .word    APP_MemManage_Handler + 1                @ #4  MemManage_Handler
    .word    APP_BusFault_Handler + 1                 @ #5  BusFault_Handler
    .word    APP_UsageFault_Handler + 1               @ #6  UsageFault_Handler
    .word    0x00000000                               @ #7  reserved
    .word    0x00000000                               @ #8  reserved
    .word    0x00000000                               @ #9  reserved
    .word    0x00000000                               @ #10 reserved
    .word    APP_SVC_Handler + 1                      @ #11 SVC_Handler
    .word    APP_DebugMon_Handler + 1                 @ #12 DebugMon_Handler
    .word    0x00000000                               @ #13 reserved
    .word    APP_PendSV_Handler + 1                   @ #14 PendSV_Handler
    .word    APP_SysTick_Handler + 1                  @ #15 SysTick_Handler
    .word    APP_WWDG_IRQHandler + 1                  @ #16 WWDG_IRQHandler
    .word    APP_PVD_IRQHandler + 1                   @ #17 PVD_IRQHandler
    .word    APP_TAMPER_IRQHandler + 1                @ #18 TAMPER_IRQHandler
    .word    APP_RTC_IRQHandler + 1                   @ #19 RTC_IRQHandler
    .word    APP_FLASH_IRQHandler + 1                 @ #20 FLASH_IRQHandler
    .word    APP_RCC_IRQHandler + 1                   @ #21 RCC_IRQHandler
    .word    APP_EXTI0_IRQHandler + 1                 @ #22 EXTI0_IRQHandler
    .word    APP_EXTI1_IRQHandler + 1                 @ #23 EXTI1_IRQHandler
    .word    APP_EXTI2_IRQHandler + 1                 @ #24 EXTI2_IRQHandler
    .word    APP_EXTI3_IRQHandler + 1                 @ #25 EXTI3_IRQHandler
    .word    APP_EXTI4_IRQHandler + 1                 @ #26 EXTI4_IRQHandler
    .word    APP_DMA1_Channel1_IRQHandler + 1         @ #27 DMA1_Channel1_IRQHandler
    .word    APP_DMA1_Channel2_IRQHandler + 1         @ #28 DMA1_Channel2_IRQHandler
    .word    APP_DMA1_Channel3_IRQHandler + 1         @ #29 DMA1_Channel3_IRQHandler
    .word    APP_DMA1_Channel4_IRQHandler + 1         @ #30 DMA1_Channel4_IRQHandler
    .word    APP_DMA1_Channel5_IRQHandler + 1         @ #31 DMA1_Channel5_IRQHandler
    .word    APP_DMA1_Channel6_IRQHandler + 1         @ #32 DMA1_Channel6_IRQHandler
    .word    APP_DMA1_Channel7_IRQHandler + 1         @ #33 DMA1_Channel7_IRQHandler
