    .word    APP_USB_LP_CAN1_RX0_IRQHandler + 1       @ #36 USB_LP_CAN1_RX0_IRQHandler
    .word    APP_CAN1_RX1_IRQHandler + 1              @ #37 CAN1_RX1_IRQHandler
    .word    APP_CAN1_SCE_IRQHandler + 1              @ #38 CAN1_SCE_IRQHandler
    .word    APP_EXTI9_5_IRQHandler + 1               @ #39 EXTI9_5_IRQHandler
    .word    APP_TIM1_BRK_IRQHandler + 1              @ #40 TIM1_BRK_IRQHandler
    .word    APP_TIM1_UP_IRQHandler + 1               @ #41 TIM1_UP_IRQHandler
