    mov.n    r5, r2                              @ 080040FC
    bne.n    L_0800410A                          @ 080040FE
    mov.n    r1, r4                              @ 08004100
    mov.n    r0, r3                              @ 08004102
    bl       swd_read_reg                        @ 08004104
    b.n      L_0800418C                          @ 08004108
L_0800410A:
    cbz      r3, L_08004112                      @ 0800410A
    cmp.n    r3, #1                              @ 0800410C
    beq.n    L_08004118                          @ 0800410E
    b.n      L_08004120                          @ 08004110
L_08004112:
    movs.n   r1, #0x1f                           @ 08004112
    movs.n   r0, #0xa                            @ 08004114
    b.n      L_0800411C                          @ 08004116
L_08004118:
    movs.n   r1, #0x1f                           @ 08004118
    movs.n   r0, #0xb                            @ 0800411A
L_0800411C:
    bl       jtag_tap_goto_state                 @ 0800411C
L_08004120:
    cmp.n    r0, #0x80                           @ 08004120
    bne.n    L_08004130                          @ 08004122
    mov.n    r1, r5                              @ 08004124
    mov.n    r0, r4                              @ 08004126
    pop.w    {r2, r4, r5, lr}                    @ 08004128
