@ dap_read_reg_checked    <- called from dap_check_ctrl_stat, dap_read_part_id, dap_power_up_debug, target_select_ap, cortexm_write_reg_verify ...
@ [swd] DAP register read wrapper that issues a RDBUFF/error read (dap_read_rdbuff) when the read ack is not OK
    .thumb_func
dap_read_reg_checked:
    push.n   {r4, lr}                            @ 08004132
    bl       dap_read_reg                        @ 08004134
    mov.n    r4, r0                              @ 08004138
    cmp.n    r4, #0x80                           @ 0800413A
